#if UNITY_EDITOR
using System;using System.IO;using System.Collections;using System.Collections.Generic;using System.Reflection;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;
namespace IslandSystem {
public class RelicReview:MonoBehaviour {
 EditorWindow view;Type vt;List<string> checks=new List<string>();const BindingFlags Flags=BindingFlags.Instance|BindingFlags.Public|BindingFlags.NonPublic;const string D="Docs/IslandSystem/Relic/";
 void Check(bool pass,string name){if(!pass)throw new Exception(name);checks.Add("PASS "+name);}
 RenderTexture Render(){view.position=new Rect(0,0,1280,741);vt.GetProperty("targetSize",Flags).SetValue(view,new Vector2(1280,720));view.SendEvent(new Event{type=EventType.Repaint});return (RenderTexture)vt.GetMethod("RenderView",Flags).Invoke(view,new object[]{Vector2.zero,false});}
 void Shot(string name){Render();var r=Render();var old=RenderTexture.active;RenderTexture.active=r;var t=new Texture2D(r.width,r.height,TextureFormat.RGB24,false);t.ReadPixels(new Rect(0,0,r.width,r.height),0,0);var a=t.GetPixels();var b=new Color[a.Length];for(int y=0;y<r.height;y++)Array.Copy(a,y*r.width,b,(r.height-1-y)*r.width,r.width);t.SetPixels(b);t.Apply();File.WriteAllBytes(D+name+".png",t.EncodeToPNG());Destroy(t);RenderTexture.active=old;}
 IEnumerator Start(){Directory.CreateDirectory(D);yield return null;vt=typeof(Editor).Assembly.GetType("UnityEditor.GameView");view=EditorWindow.GetWindow(vt);float ready=Time.realtimeSinceStartup+4;while((!RelicCore.Instance||!RelicCore.Instance.Device)&&Time.realtimeSinceStartup<ready){Render();yield return null;}yield return new WaitForSeconds(.2f);var task=Checks();while(true){bool next=false;try{next=task.MoveNext();}catch(Exception e){File.WriteAllText(D+"REVIEW.txt",string.Join("\n",checks)+"\nFAIL "+e);Debug.LogException(e);EditorApplication.Exit(2);yield break;}if(!next)break;yield return task.Current;}File.WriteAllText(D+"REVIEW.txt",string.Join("\n",checks)+"\nBackground Play Mode; offscreen GameView only; no OS input or desktop capture.");EditorApplication.isPlaying=false;}
 IEnumerator Checks(){var motor=FindAnyObjectByType<ActionMotor>();var relic=RelicCore.Instance;Check(motor&&relic&&relic.Device,"wearable instantiated in lighthouse scene");motor.ReviewMode=true;relic.ReviewMode=true;foreach(var w in FindObjectsByType<Workbench>(FindObjectsSortMode.None))w.enabled=false;var host=FindAnyObjectByType<ScratchWorkbenchHost>();if(!host){var go=new GameObject("Relic review host");go.SetActive(false);host=go.AddComponent<ScratchWorkbenchHost>();host.BackgroundReview=true;host.SuppressFocus=true;host.SavePathOverride=Path.GetFullPath("Logs/relic-review-draft.json");go.SetActive(true);}host.BackgroundReview=true;host.SuppressFocus=true;yield return null;
 vt=typeof(Editor).Assembly.GetType("UnityEditor.GameView");view=EditorWindow.GetWindow(vt);float time=Time.timeScale;var bone=motor.animator.GetBoneTransform(HumanBodyBones.LeftLowerArm);Check(relic.Device.IsChildOf(bone),"attached to left lower arm bone");Check(relic.Expansion==0,"idle closed");Debug.Log("RELIC_MOUNT_NORMAL "+relic.Device.up+" LEFT "+(-motor.transform.right));Check(Vector3.Dot(relic.Device.up,-motor.transform.right)>.6f,"device faces lateral outside of left forearm");Shot("01-Wearing");
 var cam=motor.view;float originalFov=cam.fieldOfView;cam.transform.position=relic.Device.position+relic.Device.up*.52f-relic.Device.forward*.30f+relic.Device.right*.12f;cam.transform.LookAt(relic.Device.position);cam.fieldOfView=35;Shot("02-Idle");Physics.SyncTransforms();var pt=cam.WorldToScreenPoint(relic.Hitbox.bounds.center);Check(relic.Pick(pt),"world collider hit from visible arm");relic.ReviewHover=true;yield return null;cam.transform.position=relic.Device.position+relic.Device.up*.52f-relic.Device.forward*.30f+relic.Device.right*.12f;cam.transform.LookAt(relic.Device.position);Shot("03-Hover");Physics.SyncTransforms();cam.fieldOfView=originalFov;pt=cam.WorldToScreenPoint(relic.Hitbox.bounds.center);Check(relic.HandlePointer(pt)&&host.IsOpen,"click entity opens existing host");yield return new WaitForSeconds(.35f);Check(relic.Expansion>0&&relic.Expansion<1&&motor.InputBlocked,"activation animates while input blocked");Shot("04-Activation");yield return new WaitForSeconds(.5f);Check(relic.PanelReady&&relic.Expansion==1,"petals expand before native panel reveal");Shot("05-Projection");host.HandleShortcut(KeyCode.Escape);yield return new WaitForSeconds(.5f);Check(!host.IsOpen&&!motor.InputBlocked&&relic.Expansion==0,"close retracts and restores control");
 relic.ReviewHover=false;cam.fieldOfView=60;host.HandleShortcut(KeyCode.Tab);yield return new WaitForSeconds(.6f);Check(host.IsOpen&&relic.PanelReady,"Tab opens device and panel");host.HandleShortcut(KeyCode.Tab);yield return new WaitForSeconds(.4f);Check(!host.IsOpen&&!motor.InputBlocked,"Tab closes and restores input");var hud=RelicCore.HudRect;Check(relic.HandlePointer(new Vector2(hud.center.x,Screen.height-hud.center.y)),"rendered HUD icon click accepted");yield return new WaitForSeconds(.6f);Check(host.IsOpen,"HUD opens same editor");host.ReviewToggle(false);yield return new WaitForSeconds(.4f);host.ReviewToggle(true);yield return new WaitForSeconds(.1f);host.ReviewToggle(false);yield return new WaitForSeconds(.05f);host.ReviewToggle(true);yield return new WaitForSeconds(.6f);Check(host.IsOpen&&relic.PanelReady,"rapid close/reopen retains activation");host.ReviewToggle(false);yield return new WaitForSeconds(.4f);var start=motor.transform.position;motor.ReviewAxes=Vector2.up;yield return new WaitForSeconds(.25f);motor.ReviewAxes=Vector2.zero;Check(Vector3.Distance(start,motor.transform.position)>.2f,"character moves after closing");Check(Time.timeScale==time&&motor.GetComponent<CharacterController>().enabled,"world time and character collider unchanged");Shot("06-HUD");Debug.Log("RELIC_REVIEW_PASS "+checks.Count);
 }
}
[InitializeOnLoad]public static class RelicReviewEntry {
 static RelicReviewEntry(){if(SessionState.GetBool("RelicReview",false))EditorApplication.playModeStateChanged+=Attach;}
 public static void Run(){if(!Application.isBatchMode)throw new Exception("Background only");EditorSceneManager.OpenScene("Assets/Scenes/Lighthouse_Coast_ArtBenchmark_V01.unity");SessionState.SetBool("RelicReview",true);EditorApplication.playModeStateChanged+=Attach;EditorApplication.isPlaying=true;}
 static void Attach(PlayModeStateChange s){if(s==PlayModeStateChange.EnteredPlayMode)new GameObject("Relic background review").AddComponent<RelicReview>();if(s==PlayModeStateChange.EnteredEditMode){SessionState.SetBool("RelicReview",false);EditorApplication.Exit(0);}}
}
}
#endif
